) AS (
  VALUES 
    (225::BIGINT, 'La profe casi excelente, solo que no tomen el curso a las 7 am, uno se duerme y se pierde de materia, y practiquen o si no van a mamar, la profe en buena nota y los va ayudar pero si no aprovechan eso van a andar contando puntos en la última semana, el proyecto es un trauma que todos tenemos'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Brinda apoyo']::TEXT[], '2026-07-18T00:00:00+00:00'::TIMESTAMPTZ, '519143c506afa555b9aa957726195105dda3bf8a0308badb26c9d053c1ba4334'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'La profe es muy dedicada y atenta. Las clases son 95% ejercicios entonces son cansadas. Lo peor del curso es la pésima cátedra. Los aprendizajes activos son buenos para practicar pero esperan que lo resolvamos con solo leer los capítulos del libro sin explicación previa.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-01-10T00:00:00+00:00'::TIMESTAMPTZ, '257073ac586414f53e045df132e59ef76b4b96376c85b2cbf0e068157c738847'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (225::BIGINT, 'La profe es muy carismática y califica bien los trabajos, pero a veces no daba alguna información importante sobre evaluaciones que a los otros grupos si les decían.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, 'e38b3663c46fe4916902fd018fb7a2ca2a234dcdee18655f1f62e0c497637726'::TEXT, ARRAY[933]::BIGINT[]),
    (225::BIGINT, 'muy buena opcion, explicará las veces que sea necesario y hasta ayuda con quices extras, el problema no es ella, el problema es la matada a la que te somete la cátedra.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, '2777fe67fd5a158734bc9fb516f0f2a43cf709b2069b16fa2b2c6b398294072d'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (225::BIGINT, 'La profe Laura es súper simpática en clase y explica bien. La cátedra de DT es concha con la evaluación pero la profe es considerada a la hora de calificar. Si le pide ayuda siempre la da. 100% recomendada PD: Me cago en Dibujo Técnico'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'b4e908f43cd8976527cf12e7417b5e2557dfd3a729a2762d1b540021ed7f1f19'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Se explica bastante bien, simpática, incluso si uno llega sin leer la guía puede entender la materia, los quices son duros, los exámenes aún más .'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Exámenes retadores']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '3ec7030ff427d1399ec4db730d2f980cfb72a69d8a84f60649ceb45934695d4c'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (225::BIGINT, 'La profesora hace ejercicios de buen nivel, lo que ayuda a crear soltura en el estudiante y este comprenda cómo resolver problemas, el problema es la abusiva cátedra del curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'b9b244b9ee14b1e4f06df0efd387a1209aa04a0a9736a0c3fd8ce2de1419ab4d'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (225::BIGINT, 'Los quices son relativamente fáciles, hace la clase muy din y busca la manera de que se aprenda. Lo malo es que si le pedis ayuda con el proyecto o para estudiar siempre esta detrás del palo, dice mucho y nada a la vez. Hay profes como Felipe o Mata que da hasta un ejercicio del examen final.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'f91f98ded411bdd1ef04f44f6025f1460f635300f4f1d8979cd0c9de5ddda569'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (225::BIGINT, 'La profesora es excelente y es muy alegre. Tiene todo bien organizado. En clase a veces puede ser un poco enredado, pero en la mayoría de los casos es bien claro. Califica justo, pero las rúbricas son las típicas de mante, entonces mucho cuidadado con los quices y exámenes.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2023-11-17T00:00:00+00:00'::TIMESTAMPTZ, '17eb0cb2087713d950e914fc488857c2093c2cf510658873927234ab6a3cf8ed'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (225::BIGINT, 'De las mejores profes de la escuela de ingeniería electromecánica. Las clases son presenciales pero igual las graba en teams para poder verlas. Ayuda demasiado en consulta, explica muy claro y es flexible y muy alegre. 10/10 la profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-07-13T00:00:00+00:00'::TIMESTAMPTZ, 'a7b1b06a5eff7e9efa811d13bdb0722a8d85ee19bcdcd2cc7631708a5b4b7105'::TEXT, ARRAY[933]::BIGINT[]),
    (225::BIGINT, 'Para mi es la mejor en Dibujo Industrial, tiene alguna flexibilidad en cuanto a fechas, ayuda con quices extra o eliminar algún quiz malo. Es importante tener un buen grupo de trabajo, el primer examen es difícil pero no sé desanime con el resto si se esfuerza y le pone cariño logra pasar el curso.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '1aa3aeffd99d60c634b450e7076c29ca099af96c0c105cdd88ffbe26e76cdacb'::TEXT, ARRAY[933]::BIGINT[]),
    (225::BIGINT, 'Laura es la mejor profe de dibujo industrial del Tec, explica todas las veces que sea necesario, no califica tan duro y si es necesario dar más tiempo, lo da. Además es muy comprensiva'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'b117e026ecfcf3598f24aec7e5b49fcbd32b9609ee1e2389f1a475f30fa36ad3'::TEXT, ARRAY[933]::BIGINT[]),
    (225::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2022-11-23T00:00:00+00:00'::TIMESTAMPTZ, '5a8c7e3e1de3cc4641531f57b0a371dbf5706ea65c5cfc207f2e64bb7ba1f943'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'El curso en sí ya es muy duro, pero la profe intenta que sea llevadero'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-10T00:00:00+00:00'::TIMESTAMPTZ, '8d39a29efae317ad71be8b7db90b29be2ec4ffc93bc8d0b8d54f64282916d619'::TEXT, ARRAY[933]::BIGINT[]),
    (225::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-11-03T00:00:00+00:00'::TIMESTAMPTZ, '532c85eefa0fa0e68b3ec1fe760f374f84c8f89ec5819a2f5dfecec4b64226df'::TEXT, ARRAY[933]::BIGINT[]),
    (225::BIGINT, 'Estática en general es horrible y hay que llevar todo al día, es de estudiar mucho. La profe es buena gente, explica mil veces de ser necesario y deja trabajos en clase todas las semanas. Califica bien. Puede llevar 100 en todo fácil pero el examen ya depende de uno.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'ea520fbdcf69c31a621318745f49e8a5edff0e69d7f527ff2c62faa6f8b8b1f0'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (225::BIGINT, 'El curso es complicado pero con ella se aprende mucho y lo ayuda demasiado. Es buena profe.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Deja trabajos largos']::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, '88f398f9e4ccc2f9599c0bbb280fbbfb5431bbf5201fbd0d40eaf6ab0a5361df'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2022-05-08T00:00:00+00:00'::TIMESTAMPTZ, 'a7af62d997e1e8a4c722b1758ee404294ec644153071a893a704ddee73f245e7'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'La profe es muy buena, pero el curso es duro. Y la cátedra de estática es un poco maldita. Con la profe usted aprende sí o sí y las horas consulta son demasiado aprovechables ya que explica muy bien.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'b6c04e0725098dc1ae970bd6bee803716f130d9cb12f066a7c76eda38b7bb8bd'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (225::BIGINT, 'Buena profe, ella explica algo rápido pero en general la recomiendo. Hace trabajos en clases todas las semanas y califica justo Para el proyecto que asignan ella calificó bonito. La recomiendo mucho'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-08T00:00:00+00:00'::TIMESTAMPTZ, '76e24b0f5ff046a59c220c394304bb0a3acd357a19afc7f4df2fbe65e2cd029e'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (225::BIGINT, 'En virtual la profe es muy buena, explica muy bien, aunque aveces en clase va muy rápido, pero si se le pide que vuelva a explicar, ella sin problema lo hace, hay que aprovechar las consultas, el curso es pesado'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2021-12-04T00:00:00+00:00'::TIMESTAMPTZ, '0b0c719b559af3be3d0b6e68528d82fdd14f3145b551cc52d8d3c3ed9398d9ce'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'El curso en sí es complicado pero ella trata de ayudar bastante y si es necesario explica con manzanitas'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-10-27T00:00:00+00:00'::TIMESTAMPTZ, '2d19b141ae967a0251b3474e3f90b9b77c1661d4c96526c783cb33a011514914'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (225::BIGINT, 'La profe es excelente pero si buscas pasar fácil sin aprender ella no es la opción, porque con ella vas a tener que aprender si o si debido a que califica bastante duro, pero siempre esta dispuesta a ayudar. Consejo: vaya a consulta si quiere sobrevivir a este curso infernal'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-07-26T00:00:00+00:00'::TIMESTAMPTZ, '20438a7e4ac15219985f8b3310be734145100a2ec743566d5e70f70d46ab5974'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Excelente profe, las clases son pesadas pero es por el curso, da muchos ejemplos y en consulta siempre ayuda. La mejor profe para llevar este curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2021-07-22T00:00:00+00:00'::TIMESTAMPTZ, '3fd4c0a626053fe8a4e4b819813a641f90389149e8c4f4cdb41c099363a86664'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'La profe es muy buena explica todo muy claro, sólo que explica un poco rápido, pero siempre vuelve a explicar las veces que haga falta. El curso si es bastante pesado y requiere de mucha practica, la profe ayuda bastante en las tareas y seguimientos aprovechenla para consulta.Más que recomendada.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, '85b40a7c13f164aa9be0c2769fb03bd599ea4cbc713408eb1e16231a77ffd994'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Es una excelente profe, sabe explicar muy bien y siempre saca su tiempo para volver a explicar cuando es necesario. El curso requiere mucho tiempo y puede tener sus cosas complicadas, pero en consulta ella siempre está disponible y hubo veces en las que se quedo más tiempo para poder ayudar a todos'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '019c16997a8bfdd6d6b20ebc805b0ef2164a6816004b9588a18325dc5a0e8b5c'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Muy buena profe. Llevé el curso con ella el primer semestre del 2018, lastimosamente me quedé, pero no fue por la profesora, sino por mis pocas bases y hasta por un poco de vagabundería. Explica las veces que sea necesario, es muy accesible en consultas.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2021-02-16T00:00:00+00:00'::TIMESTAMPTZ, 'f3eb32d0baec71a11b1317c71ae9a1157f83e98a6064ef1b8c8de796cd0245c2'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Buena profe, explicaba los temas aunque no debía hacerlo y daba bastantes ejemplos. Flexible con evaluaciones. Recomendada para virtual'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'df3c790467e13f871fdf9f1012f5c079df74032fb1c632ef6717e643b40d6736'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (225::BIGINT, 'Se enreda de vez en cuando pero todo bien, las clases son un poco aburridas, pero atiende mil veces la misma duda si es necesario'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'b2e1b242882ff0a7a10c3e77602d9631bf8a7c655c329287982a2e31c4c1522c'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (225::BIGINT, 'Excelente profesora, muy buena explicando y super comprensiva, te ayuda y te explica las veces que sean necesarias. El curso es pesado por la cátedra, en todas las semanas hay una evaluación ya sea tarea quiz o examen. Hay que practicar bastante para los examenes y quices.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '0bd936f1445bdf4f56bd89771f536339d1ef498e3baeade7374073173262f066'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (225::BIGINT, 'La profe se encarga de hacer bastantes ejemplos, antes de cada examen hace una lección de repaso. Es super compresiva si a uno se le olvidó o no le dio chance de subir una evaluación.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'c11954b468577ddc9fe15ad2e068fc2a0797ff9f837441b0aa51615579a196c4'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (225::BIGINT, 'Es una teja de profe y ayuda las veces que sean necesarias para entender, pero deja MUCHAS tareas y se extiende 1 hora y media despues de lo estimado(sin broma).Tambien da muchas vueltas, lo que hace que el estudiante pierda mucho interes durante la clase.No entrega notas sino hasta finalde semestr'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Brinda apoyo']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '6fd6d6dbcbe0fcea15ed2a5ab3ce1026ba46af3b4ac179ce375be0ece96219bd'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Una profe muy amable, califica justo, comprensiva. Si tiene que explicar algo otra vez, lo hace sin ningún problema'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '609e01452fc50ef204e78416be79641b4e6514feb9189d4f29669355cd053fda'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Una excelente profesora, da ejercicios para realizar en la casa y si quedan dudas, las atiende con demasiada paciencia en horas de consulta.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '936efc919877a8f4886077de4ba466cd56b314dac7ca5634a3b13b2048b32f13'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (225::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '309be37a1ff31a2d8b8d37363a9945a5af425c063dc11218599dfd4438e9f5d3'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Es una profe que realmente le importa que el estudiante aprenda,explica cuantas veces sea necesario y en horas de consulta ayuda con las tareas, las clases son muy largas y cansadas pero da suficiente tiempo para entregar los seguimientos semanales.Lo malo es que se atrasa entregando las notas.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '27bf7cb7e13f3ad497dd72cdf89b236f4945a5190fbe45293fa2253e1a974a6c'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Las clases son muy largas pero todo queda grabado, explica todas las veces que se le pregunté y de buena forma.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '59a8814bf6644eebc779641034390097c169dd9fa31621c68968fdea0f6ba65e'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Explica un poco raro pero virtual se puede llevar Bien porque hay videos. E igual la profe ayuda un monton en las horas de consulta.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Brinda apoyo']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'd1ba48c0be651e3ff4cdaa63ff09279114088138df5a78c9f676728310c9adec'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'En sí el curso requiere mucho tiempo, la asistencia no es obligatoria pero hay seguimiento semanal que la profe pide al final del día de la clase. Siempre ayuda y explica cuando uno no entiende. Lo único malo es que es muy desordenada, se atrasa mucho con las evaluaciones entonces no sabes como vas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '4905abb7e123195dc1ccc72473752972e43f668fec9e184185b74245cde296d7'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Es demasiado buena profesora, entiende que la clase puede ser un poco confusa entonces si tiene que explicar algo 3 veces lo va a hacer y siempre de una forma amigable'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Clases excelentes']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '0e93e3ed7e53e0401c2196d333af3afeba1e85bc03a515584e2fd48bce8d721a'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Por la clase, deja muchos trabajos largos. Pero son de cátedra. Si no entiende, vaya a consulta, le va ayudar en todo lo que pueda. Las clases sí son muy largas, en virtual abarca las 4 horas, llegando casi a 5. Pero es por explicar y ayudar a los estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '2e3849647d78da42972c14d749851cdc15b73b5a51e26258ee36410595bdd8ab'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Es muy buena como profe. Muy seria pero en lo personal me ayudo mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2020-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'cb2db69794333c79280103d1fbac7a92f972f2705c34cecd8a8b58a0f5e08723'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-06-05T00:00:00+00:00'::TIMESTAMPTZ, '88337203504a5832f22f207c3a56708d0924d943881eda1b070a9ed0f01be7fa'::TEXT, ARRAY[1179]::BIGINT[]),
    (225::BIGINT, 'Excelente profe! Siempre dispuesta a ayudar al estudiante y de repetir lo mismo 10 veces si es necesario. Yo si volvería a matricular con ella!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases largas']::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'ef2369ee9308e37feaeba6cba193f4d2185caf64c8713a60a1510292ea393d47'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Buena profe y pura vida'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-25T00:00:00+00:00'::TIMESTAMPTZ, '0ae39eee29f7fa54f44ded5aaa3f7b457ff97592dd6bb9f5d7f23052d0ee6a67'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Es lo mejor que tiene la escuela de Electromecánica, la recomendaría para cualquier curso de esta escuela, no tiene comparación tanto como profe, como persona'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-18T00:00:00+00:00'::TIMESTAMPTZ, '2cf7198ed415c165389c5b339903aaf32529a1eb203c6fd4e58b012c4765532f'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (225::BIGINT, 'Muy buena profesora, el curso es un poco difícil, pero ella hace que uno no lo sienta. Ayuda mucho dentro y fuera de clase. Es super amable y comprensible. Es ingeniera mecánica y sabe bastante de la materia.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-08-16T00:00:00+00:00'::TIMESTAMPTZ, '249a919e119f6a06f81cd15199d922105aab08ea91fdba4f9b8a17abe5b9d40a'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Es muy buena persona y tiene la intención de ayudar a todos pero la dificultad del curso complica las cosas. Durante los ejercicios se suele equivocar.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'ab0d872e47b3012b9026e0b142d65e111a73d421391ab856b633e77a7d1c1905'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (225::BIGINT, 'La profesora es excelente persona y está muy interesada en que el estudiante aprenda y entienda. Se confunde y todavía no entiende muy bien la dinámica del curso. Los quices son difíciles y largos.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-06T00:00:00+00:00'::TIMESTAMPTZ, '910cdb54a973df273bd95c95b9c2721425b066072b96eba0d032709885ba94fb'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (225::BIGINT, 'Muy buena para ser la primera vez que da el curso, se enreda un poco pero al final se entiende, explica las veces que sea necesario. Muy buena persona'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-05T00:00:00+00:00'::TIMESTAMPTZ, '2c25b9b8f496882f41cdc61e497dd4045041d5b59acb4e75af73371ad795605b'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (225::BIGINT, 'Demasiado buena, exámenes fáciles si se prepara(solo tiene que hacer todas las tareas y ponerle atención), califica justo y ayuda mucho en consulta, explica todas las veces necesarias.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-10-27T00:00:00+00:00'::TIMESTAMPTZ, '5948eea3a60c68fb5effac4d990d70683eaa259367745fec885b81c68283f577'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-22T00:00:00+00:00'::TIMESTAMPTZ, 'cafe6b18d2d6a7e8d7adabaa57b49f54aa79230f774621ba9024674ccc3c9ea9'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Explica muy rápido y se enreda sola, pero usted hágale las preguntas que ocupe que ella le va a ayudar con todo, es súper buena gente y califica regular.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, '382250e7c48cdcf968385e4e36f336453934e8c189132478188a68d1aa53ceb6'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Es muy buena profe, solo que aveces se enreda un poquito, pero por lo demás es excelente se preocupa por el estudiante y en serio trata de que todos pasen. Super recomendada'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'd45705082bf18b73ec888cfef49f22e24a515b46e500df27ed7678d44688ffa0'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Es buena profe aunque a veces se enreda un poco. Califica muy bien siempre pensando en el estudiante.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-08T00:00:00+00:00'::TIMESTAMPTZ, '0b610609bc51d4de8475995e4e2afb177a78c9d7f465545c3e24d832a54b3c9a'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'De vez en cuando se enreda explicando, pero son pocas veces. La verdad ayuda bastante y califica justo. Si puede matricula con ella no lo dude.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-04T00:00:00+00:00'::TIMESTAMPTZ, '0f599450f835d02c2415fd551e735a7c1c4bc2295367599cf5d7a7e91cbc7337'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Explica muy confuso. Se preocupa por sus estudiantes y ayuda.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas']::TEXT[], '2018-01-28T00:00:00+00:00'::TIMESTAMPTZ, '90f7058a64eea9dedde207f212a489e895e1865789fc474fa35e2ab9fb26e2da'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Explica un poco confuso, pero sí se preocupa por sus estudiantes y ayuda mucho; suele ir rápido, así que hay que ponerle mucha atención.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2017-12-15T00:00:00+00:00'::TIMESTAMPTZ, '4537c06d9a0b4147be67ca02ec0a83a2c1ef6c060131e03b755e1e62ff1382b3'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Ayuda bastante, sin embargo se enreda dando la clase y cuesta seguirle el ritmo, los quices y exámenes son un poco difíciles.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2017-12-08T00:00:00+00:00'::TIMESTAMPTZ, '3234600ad08c6b9fb9cab9f088de907e866adee2e8751423140e8d9a4c94d442'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Se complica a veces, pero explica lo necesario, si usted no tiene bases le va a costar un poco, pero no es imposible. Ayuda bastante'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, '0ee3b37c0654387ad4799f30022255fc0b9efcb9764e76e2bc85cf4f07e86f3f'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'En general, el curso se hace fácil con ella. Califica bonito. Dura muchísimo en entregar evaluaciones.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Brinda apoyo']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'e533688c27f63dcc8b3a12459e249aeb8398669bae60eeb86eb5e3d4da04dc27'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Se complica demasiado para explicar cosas muy sencillas, pero califica suave. Recomiendo ver a Dostin Hurtado en youtube para AutoCAD y Solid works porque a ella no le van a entender con mucha facilidad.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-09-23T00:00:00+00:00'::TIMESTAMPTZ, 'c6ee5486b554d2b34c2c7ef847fd303e7112b5efa18fb5eeb424b2729d2dfe2a'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'La mejor profe para este curso. Realmente se preocupa por los estudiantes y busca la manera de que todos entiendan y pasen. Mil veces recomendada.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '77078ded81dd2876aff862d80797008bf2d96c6970fb2a5c42404be9ac825a2c'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'La recomiendo demasiado y más si le cuesta esta materia. Ella le explica tan bien a uno y se nota que quiere lo mejor para los estudiantes y que aprendan. Como persona también es súper buena y creo que califica de acuerdo a la persona (si ella sabe que le cuesta, no califica tan rudo).'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'afa15632fb43d8de4575c6cfb082303c8feb335658c5ab19a15baab6b6c9c4cc'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Explica bastante bien y las veces que sea necesario. En consulta ayuda mucho, es muy buena gente. Califica justo; sus tareas, prácticas supervisadas y exámenes son promedio. Totalmente recomendada.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-20T00:00:00+00:00'::TIMESTAMPTZ, '5587397ab180a44c469aa07e632dc44670c3b669302a1af8ab1b91351a901fa6'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'Califica muy suave'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'b4f77eba424e629c0952c2a3aa6420ff096abb423ff145570e8c4e25033830eb'::TEXT, ARRAY[610]::BIGINT[]),
    (225::BIGINT, 'La profe es súper buena, nada más que el curso es un poco tedioso entonces si quita mucho tiempo, pero va ser así con cualquier profe.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2017-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'fdc4ceb97426b165b4dbbce9c7a70d85817720bd6cde65025c59805271a889ef'::TEXT, ARRAY[610]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
